L["Consulting a suspiciously old map..."] = "Consultando un mapa sospechosamente viejo..."
L["Measuring the Deeprun Tram with a ruler..."] = "Midiendo el Tranvía Subterráneo con una regla..."
L["Waiting for the goblin cartographer to sober up..."] = "Esperando a que al cartógrafo goblin se le pase la borrachera..."
L["Checking the shortcut for Defias..."] = "Comprobando que no haya Defias en el atajo..."
L["Counting the stairs in Ironforge..."] = "Contando los escalones de Forjaz..."
L["|cff40ff40Arrived|r"] = "|cff40ff40Has llegado|r"
L["|cffffd100Turn in the quest|r"] = "|cffffd100Entrega la misión|r"
L["|cffffd100In the quest area|r"] = "|cffffd100En la zona de misión|r"
L["No way there found"] = "No se ha encontrado camino"
L["That spot can't be reached on foot from here (a cliff in the way)."] = "Ese lugar no se puede alcanzar a pie desde aquí (hay un acantilado en medio)."
L["|cffffd100Use %s|r (to %s)"] = "|cffffd100Usa %s|r (a %s)"
L["|cffffd100Learn the flight path, then fly to %s|r"] = "|cffffd100Aprende la ruta de vuelo y vuela a %s|r"
L["Board the %s to %s"] = "Sube a %s hacia %s"
L["to the %s (then to %s)"] = "hasta %s (luego a %s)"
L["|cffffffffETA %s|r"] = "|cffffffffLlegada %s|r"
L["All stops: %s"] = "Todas las paradas: %s"
L["Next %d stops: %s"] = "Próximas %d paradas: %s"
L["|cffffd100! In a quest area|r"] = "|cffffd100! En una zona de misión|r"
L["Defeat %s"] = "Derrota a %s"
L["Defeat the boss"] = "Derrota al jefe"
L["Upstairs: %s"] = "Arriba: %s"
L["Downstairs: %s"] = "Abajo: %s"
L["Below you (down a lift)"] = "Debajo de ti (baja en ascensor)"
L["Above you (up a lift)"] = "Encima de ti (sube en ascensor)"
L["Below you, %s down"] = "Debajo de ti, %s más abajo"
L["Above you, %s up"] = "Encima de ti, %s más arriba"
L["Press a key..."] = "Pulsa una tecla..."
L["Not bound"] = "Sin asignar"
L["|cffff6060Not in combat.|r"] = "|cffff6060No en combate.|r"
L["Was: %s"] = "Antes: %s"
L["|cffff6060That key can't be used.|r"] = "|cffff6060Esa tecla no se puede usar.|r"
L["Click, then press a key (Shift, Ctrl or Alt with it if you like) or a controller button. The same key shows and hides the map. Escape cancels, right-click clears it. Also in the game's Key Bindings, under AddOns, and in Options > Controller."] = "Haz clic y pulsa una tecla (con Mayús, Ctrl o Alt si quieres) o un botón del mando. La misma tecla muestra y oculta el mapa. Esc cancela, clic derecho la borra. También en la Asignación de teclas del juego, en Accesorios, y en Opciones > Mando."
L["Press a key or button..."] = "Pulsa una tecla o un botón..."
L["|cffff6060Controller UI on: a keyboard key only (its tooltip says why).|r"] = "|cffff6060Interfaz de mando activada: solo una tecla del teclado (su descripción explica por qué).|r"
L["Quick Find: no %s known on %s, so no route off it. Search Places lists the ones elsewhere."] = "Búsqueda rápida: no se conoce ningún %s en %s, así que no hay ruta fuera de allí. Buscar lugares muestra los de otros sitios."
L["Thanks to |cffffd100jigrobbulus|r, creator of OpenMap, for making it open source, so its stitched world map could be built into AzerothGPS as the OpenMap map style. Click the address to select it, then Ctrl+C to copy it:"] = "Gracias a |cffffd100jigrobbulus|r, creador de OpenMap, por hacerlo de código abierto, lo que permitió integrar su mapa del mundo unido en AzerothGPS como el estilo de mapa OpenMap. Haz clic en la dirección para seleccionarla y pulsa Ctrl+C para copiarla:"
L["|cffffd100What is kept|r"] = "|cffffd100Qué se guarda|r"
L["Roads and walls you drew or erased in earlier versions (they still guide your routes), your pins, and the way you went when you reached a stop clearly faster than estimated. Positions, and your pins' names and icons: no character or realm names. Copy Map Data... includes what you tick there."] = "Los caminos y muros que dibujaste o borraste en versiones anteriores (siguen guiando tus rutas), tus chinchetas y el camino que seguiste cuando llegaste a una parada claramente antes de lo estimado. Posiciones, y los nombres e iconos de tus chinchetas: ningún nombre de personaje ni de reino. Copiar datos del mapa... incluye lo que marques allí."
L["|cffffd100Where it is kept|r"] = "|cffffd100Dónde se guarda|r"
L["On your PC, in this addon's saved variables (WTF\\Account\\<account>\\SavedVariables\\AzerothGPS.lua). Addons can't send anything from the game."] = "En tu PC, en las variables guardadas de este accesorio (WTF\\Account\\<cuenta>\\SavedVariables\\AzerothGPS.lua). Los accesorios no pueden enviar nada desde el juego."
L["|cffffd100How to report a map problem or share your map data|r"] = "|cffffd100Cómo informar de un problema del mapa o compartir tus datos del mapa|r"
L["1. Type |cffffd100/reload|r (it saves all your edits, so every one is copied), then click |cffffd100Copy Map Data...|r and press |cffffd100Ctrl+C|r."] = "1. Escribe |cffffd100/reload|r (guarda todos tus cambios, para que se copien todos), haz clic en |cffffd100Copiar datos del mapa...|r y pulsa |cffffd100Ctrl+C|r."
L["2. Paste it in either place (click an address below, Ctrl+C, and open it in your browser):"] = "2. Pégalo en cualquiera de estos sitios (haz clic en una dirección de abajo, Ctrl+C, y ábrela en tu navegador):"
L["    |cffffd100Report form|r: the first address is the report form on azerothgps.com."] = "    |cffffd100Formulario|r: la primera dirección es el formulario de informes de azerothgps.com."
L["    |cffffd100Discord|r: the second is the AzerothGPS Discord."] = "    |cffffd100Discord|r: la segunda es el Discord de AzerothGPS."
L["3. Name the zone and say what's wrong with the map there."] = "3. Indica la zona y qué está mal en el mapa allí."
L["Map problems that check out are fixed in a later version, for everyone. Your pins stay yours, to share with"] = "Los problemas del mapa que se validan se corrigen en una versión posterior, para todos. Tus chinchetas siguen siendo tuyas, para compartirlas con"
L["other players as you like: they're never put into AzerothGPS's own data."] = "otros jugadores como quieras: nunca se incluyen en los datos propios de AzerothGPS."
L["Nothing picked to copy: tick what to include above."] = "No hay nada elegido para copiar: marca arriba qué incluir."
L["%d line of map data. Press |cffffd100Ctrl+C|r to copy (it's all selected), then paste it in the report form on azerothgps.com or on the AzerothGPS Discord (see How to share). Missing an edit? Type |cffffd100/reload|r and copy again."] = "%d línea de datos del mapa. Pulsa |cffffd100Ctrl+C|r para copiar (ya está todo seleccionado) y pégala en el formulario de azerothgps.com o en el Discord de AzerothGPS (ver Cómo compartir). ¿Falta algún cambio? Escribe |cffffd100/reload|r y vuelve a copiar."
L["%d lines of map data. Press |cffffd100Ctrl+C|r to copy (it's all selected), then paste it in the report form on azerothgps.com or on the AzerothGPS Discord (see How to share). Missing an edit? Type |cffffd100/reload|r and copy again."] = "%d líneas de datos del mapa. Pulsa |cffffd100Ctrl+C|r para copiar (ya está todo seleccionado) y pégalas en el formulario de azerothgps.com o en el Discord de AzerothGPS (ver Cómo compartir). ¿Falta algún cambio? Escribe |cffffd100/reload|r y vuelve a copiar."
L["no map data to share yet: roads or walls you drew or erased, faster trips, pins"] = "aún no hay datos del mapa que compartir: caminos o muros que dibujaste o borraste, trayectos más rápidos, chinchetas"
L["Your Map Data"] = "Tus datos del mapa"
L["Unticked: left out of the copy."] = "Sin marcar: se excluye de la copia."
L["Sharing Your Map Data"] = "Compartir tus datos del mapa"
L["Copy Map Data..."] = "Copiar datos del mapa..."
L["AzerothGPS's work: measuring..."] = "Trabajo de AzerothGPS: midiendo..."
L["AzerothGPS's work: %.1f ms a second, %.1f%% of the time"] = "Trabajo de AzerothGPS: %.1f ms por segundo, el %.1f%% del tiempo"
L["AzerothGPS Options"] = "Opciones de AzerothGPS"
L["General"] = "General"
L["The GPS map window. Also: left-click the minimap button, a key (at the end of this section), or /agps toggle."] = "La ventana del mapa GPS. También: clic izquierdo en el botón del minimapa, una tecla (al final de esta sección) o /agps toggle."
L["Lock map position"] = "Bloquear posición del mapa"
L["Locks the map in place. Unlocked: drag the window frame's title bar (or the Move tab without the frame, or Shift+drag the map) to move it."] = "Fija el mapa en su sitio. Desbloqueado: arrastra la barra de título del marco de la ventana (o la pestaña Mover sin el marco, o Mayús+arrastrar el mapa) para moverlo."
L["Window frame"] = "Marco de la ventana"
L["The game-style window frame around the map: title bar, logo and close button. Off: just the map."] = "El marco de ventana al estilo del juego alrededor del mapa: barra de título, logotipo y botón de cerrar. Desactivado: solo el mapa."
L["Reopen following me"] = "Reabrir siguiéndome"
L["With a route set: if you hid the map while looking around it (dragged or zoomed out to the world map), it opens again centered on you, following your position. Off: it opens where you left it (the button at the bottom right brings it back to you)."] = "Con una ruta fijada: si ocultaste el mapa mientras lo explorabas (arrastrado o alejado al mapa del mundo), se vuelve a abrir centrado en ti, siguiendo tu posición. Desactivado: se abre donde lo dejaste (el botón de abajo a la derecha lo devuelve a ti)."
L["Zoom in near a stop"] = "Acercar cerca de una parada"
L["Within 50 yards of your next stop, the map zooms in smoothly so you can see exactly where it is, and back out to your zoom once you're there. Zooming yourself keeps your zoom for that stop."] = "A menos de 50 yd de tu próxima parada, el mapa se acerca suavemente para que veas exactamente dónde está, y vuelve a tu zoom al llegar. Si cambias el zoom tú, se mantiene el tuyo para esa parada."
L["Turn the map with me"] = "Girar el mapa conmigo"
L["On: the map turns so that where you face is up (heading-up). Off: north stays up and the arrow turns. Not in the game's world map: north stays up there, as on the game's map."] = "Activado: el mapa gira para que hacia donde miras quede arriba (orientado según la marcha). Desactivado: el norte queda arriba y gira la flecha. No en el mapa del mundo del juego: allí el norte queda arriba, como en el mapa del juego."
L["Size"] = "Tamaño"
L["Can't be smaller than %d with your quick buttons: move some to the menu or hide them (Quick buttons page)."] = "No puede ser menor de %d con tus botones rápidos: pasa algunos al menú u ocúltalos (página Botones rápidos)."
L["Width"] = "Ancho"
L["Can't be narrower than %d with your quick buttons going right: put some going up or hide them (Quick buttons page)."] = "No puede ser más estrecho de %d con tus botones rápidos hacia la derecha: pon algunos hacia arriba u ocúltalos (página Botones rápidos)."
L["Height"] = "Alto"
L["Resize from the corner"] = "Cambiar tamaño desde la esquina"
L["Drag the map window's bottom-right corner to resize it (on by default). While Lock map position is on, the corner doesn't resize; unlock the map and it does again. Off: the size only changes with the slider above."] = "Arrastra la esquina inferior derecha de la ventana del mapa para cambiar su tamaño (activado por defecto). Con Bloquear posición del mapa activado, la esquina no cambia el tamaño; desbloquea el mapa y vuelve a hacerlo. Desactivado: el tamaño solo cambia con el control deslizante de arriba."
L["Any shape"] = "Cualquier forma"
L["Dragging the corner sets the map's width and height separately, to any shape (a wide map on a wide or 4K screen, say). Off (the default): the map stays square."] = "Arrastrar la esquina ajusta el ancho y el alto del mapa por separado, con cualquier forma (p. ej., un mapa ancho en una pantalla panorámica o 4K). Desactivado (por defecto): el mapa sigue siendo cuadrado."
L["While Lock map position is off, you can also drag the map's bottom-right corner to any width and height."] = "Con Bloquear posición del mapa desactivado, también puedes arrastrar la esquina inferior derecha del mapa a cualquier ancho y alto."
L["Show/hide key"] = "Tecla mostrar/ocultar"
L["Key doesn't show the map in combat"] = "La tecla no muestra el mapa en combate"
L["In combat, pressing the show/hide key doesn't show the map, so a press by mistake can't pop it up mid-fight. It can still hide the map, and a map already showing stays. The minimap button and /agps toggle work as usual."] = "En combate, pulsar la tecla mostrar/ocultar no muestra el mapa, así que una pulsación por error no lo abre en plena pelea. Sí puede ocultarlo, y un mapa ya visible se queda. El botón del minimapa y /agps toggle funcionan como siempre."
L["Show distances in"] = "Mostrar distancias en"
L["Yards (the game's)"] = "Yardas (las del juego)"
L["Meters and kilometers"] = "Metros y kilómetros"
L["Feet and miles"] = "Pies y millas"
L["Minimap button"] = "Botón del minimapa"
L["The AzerothGPS button on the game's minimap. Without it, /agps opens this window."] = "El botón de AzerothGPS en el minimapa del juego. Sin él, /agps abre esta ventana."
L["Chat"] = "Chat"
L["Search"] = "Búsqueda"
L["Find NPCs met in several places"] = "Encontrar PNJ vistos en varios sitios"
L["NPCs you've talked to in places far apart (a guard, a supplier in every town) are left out of the search. On: they're found too, at the place you met them nearest you."] = "Los PNJ con los que has hablado en sitios muy distantes (un guardia, un proveedor en cada pueblo) se excluyen de la búsqueda. Activado: también aparecen, en el sitio donde los viste más cercano a ti."
L["Performance"] = "Rendimiento"
L["For a slower PC: the same routes, worked out and drawn less often."] = "Para un PC más lento: las mismas rutas, calculadas y dibujadas con menos frecuencia."
L["Use Low-End Settings"] = "Usar ajustes de gama baja"
L["Restore Defaults"] = "Restablecer valores"
L["Map redraws per second"] = "Redibujados del mapa por segundo"
L["The setting that saves the most: at 10 the map needs about half the work it does at 20, and still follows you smoothly. Standing still, it only redraws when something changes."] = "El ajuste que más ahorra: a 10, el mapa necesita más o menos la mitad de trabajo que a 20, y te sigue con fluidez. Si estás quieto, solo se redibuja cuando algo cambia."
L["Work out a route you've left at most every"] = "Recalcular una ruta abandonada como mucho cada"
L["%d s"] = "%d s"
L["Off the route (fighting, gathering, or going your own way), it's worked out again from where you are. Less often is less work; the route catches up with you a little later."] = "Fuera de la ruta (luchando, recolectando o yendo por tu cuenta), se vuelve a calcular desde donde estás. Con menos frecuencia hay menos trabajo; la ruta te alcanza un poco más tarde."
L["Stops routed and drawn ahead"] = "Paradas calculadas y dibujadas por delante"
L["How many of the route's stops are worked out and drawn at a time; the next come in as you reach them. Every stop is still in the fastest order and on the map, and the ones further on are listed with an estimated distance until they're routed."] = "Cuántas paradas de la ruta se calculan y dibujan a la vez; las siguientes se añaden al llegar a ellas. Todas las paradas siguen en el orden más rápido y en el mapa, y las más lejanas aparecen con una distancia estimada hasta que se calcula su ruta."
L["Gentle background work"] = "Trabajo suave en segundo plano"
L["Walks around obstacles and the road data (after a /reload) are worked out in smaller slices of each frame: fewer stutters on a slow PC. The first route after a /reload, and walks off the roads, take a little longer to appear."] = "Los rodeos de obstáculos y los datos de caminos (tras un /reload) se calculan en porciones más pequeñas de cada fotograma: menos tirones en un PC lento. La primera ruta tras un /reload y los tramos fuera de los caminos tardan un poco más en aparecer."
L["Direction arrow"] = "Flecha de dirección"
L["Turn the arrow every frame"] = "Girar la flecha en cada fotograma"
L["On: the arrow turns with every frame, as smoothly as the game runs. Off: 20 times a second, less work at high frame rates."] = "Activado: la flecha gira en cada fotograma, con la fluidez del juego. Desactivado: 20 veces por segundo, menos trabajo con tasas de fotogramas altas."
L["Other settings to improve performance"] = "Otros ajustes para mejorar el rendimiento"
L["Fewer icons on the map (Map icons, or the round button at the map's bottom-left): herbs, ore, quests and points of interest; quest areas' outlines off; and a smaller map."] = "Menos iconos en el mapa (Iconos del mapa, o el botón redondo de abajo a la izquierda del mapa): hierbas, minerales, misiones y puntos de interés; sin contornos de zonas de misión; y un mapa más pequeño."
L["Map opacity"] = "Opacidad del mapa"
L["Fade the map while moving"] = "Atenuar el mapa al moverte"
L["While you move, the map fades to the opacity below, leaving the route, the stop markers and your arrow as they are. It comes back a moment after you stop, or right away when you point at the map."] = "Mientras te mueves, el mapa se atenúa a la opacidad de abajo, sin cambiar la ruta, los marcadores de parada ni tu flecha. Vuelve un momento después de pararte, o al instante al apuntar al mapa."
L["Map opacity while moving"] = "Opacidad del mapa al moverte"
L["Click-through"] = "Clics a través"
L["Clicks go to the game world (targeting, the camera), not the map or arrow."] = "Los clics van al mundo del juego (selección de objetivo, cámara), no al mapa ni a la flecha."
L["Click-through while moving"] = "Clics a través al moverte"
L["While you move, the map and the direction arrow ignore the mouse, so a click there targets or turns the camera instead. They take clicks again a moment after you stop."] = "Mientras te mueves, el mapa y la flecha de dirección ignoran el ratón, así que un clic ahí selecciona objetivo o gira la cámara. Vuelven a aceptar clics un momento después de pararte."
L["Click-through in combat"] = "Clics a través en combate"
L["In combat, the map and the direction arrow ignore the mouse, so a click there targets or turns the camera instead."] = "En combate, el mapa y la flecha de dirección ignoran el ratón, así que un clic ahí selecciona objetivo o gira la cámara."
L["In combat"] = "En combate"
L["Hide the map"] = "Ocultar el mapa"
L["Hidden while you're in combat, so nothing on it gets clicked by mistake mid-fight. It comes back when combat ends."] = "Oculto mientras estás en combate, para no pulsar nada por error en plena pelea. Vuelve al terminar el combate."
L["Map opacity in combat"] = "Opacidad del mapa en combate"
L["Hide the direction arrow"] = "Ocultar la flecha de dirección"
L["Hidden while you're in combat. It comes back when combat ends."] = "Oculta mientras estás en combate. Vuelve al terminar el combate."
L["Arrow opacity in combat"] = "Opacidad de la flecha en combate"
L["Routing"] = "Rutas"
L["Avoid zones too high for your level"] = "Evitar zonas de nivel demasiado alto"
L["Routes go around zones whose levels are red for your character (their lowest level more than 4 above yours) when there's another way, like the other faction's towns. The zones you start and end in don't count."] = "Las rutas rodean las zonas cuyos niveles salen en rojo para tu personaje (su nivel mínimo supera el tuyo en más de 4) cuando hay otro camino, igual que los pueblos de la otra facción. Las zonas de inicio y fin no cuentan."
L["Use flight paths"] = "Usar rutas de vuelo"
L["Routes take flights (connecting ones too) between the flight masters this character knows, when that's faster. The addon learns which ones you know from the flight map: open it once at any flight master."] = "Las rutas usan vuelos (también con escalas) entre los maestros de vuelo que conoce este personaje, cuando es más rápido. El accesorio aprende cuáles conoces del mapa de vuelo: ábrelo una vez en cualquier maestro de vuelo."
L["Quest route: only this zone"] = "Ruta de misiones: solo esta zona"
L["The Quest Route button takes only the quests whose objective or turn-in is in the zone you're in (a city counts as its zone). Off: every quest in your log, anywhere."] = "El botón Ruta de misiones solo incluye las misiones cuyo objetivo o entrega está en tu zona actual (una ciudad cuenta como su zona). Desactivado: todas las misiones de tu registro, estén donde estén."
L["Quest route: only tracked quests"] = "Ruta de misiones: solo misiones seguidas"
L["The Quest Route button takes only the quests you track: the ones Questie's tracker shows when it's on, else the ones ticked to track in the quest log. Off: every quest in your log."] = "El botón Ruta de misiones solo incluye las misiones que sigues: las que muestra el rastreador de Questie si está activado, si no las marcadas para seguir en el registro de misiones. Desactivado: todas las misiones de tu registro."
L["Use hearthstone"] = "Usar piedra de hogar"
L["Routes may start with your Hearthstone (or a shaman's Astral Recall) when it's in your bags, off cooldown, and faster. Home is your inn's town; the exact spot is learned after your first hearth. The directions say when; click the button beside them to use it."] = "Las rutas pueden empezar con tu piedra de hogar (o el Regreso astral del chamán) cuando la llevas en las bolsas, no está en tiempo de reutilización y es más rápido. El hogar es el pueblo de tu posada; el punto exacto se aprende tras usarla la primera vez. Las indicaciones dicen cuándo; haz clic en el botón de al lado para usarla."
L["Use class teleports and teleport items"] = "Usar teletransportes de clase y objetos"
L["Routes may start with a mage's teleport (with a Rune of Teleportation), Teleport: Moonglade, or an engineer's Dimensional Ripper - Everlook or Ultrasafe Transporter: Gadgetzan (with the specialization it needs) when it's known or in your bags, off cooldown, and faster. Click the button beside the directions to use it."] = "Las rutas pueden empezar con un teletransporte de mago (con una Runa de teletransporte), Teletransporte: Claro de la Luna, o el Destripador dimensional: Vista Eterna o el Transportador ultraseguro: Gadgetzan de un ingeniero (con la especialización necesaria) cuando lo conoces o está en tus bolsas, no está en tiempo de reutilización y es más rápido. Haz clic en el botón junto a las indicaciones para usarlo."
L["Avoid the other faction's towns"] = "Evitar pueblos de la otra facción"
L["Routes keep away from the other faction's guards (their towns and camps, and where their guards patrol), going around when there's a way. A stop inside one is still reached, the shortest way in."] = "Las rutas se alejan de los guardias de la otra facción (sus pueblos y campamentos, y por donde patrullan), rodeándolos cuando hay camino. A una parada dentro de uno se llega igualmente, por la entrada más corta."
L["Road tolerance"] = "Tolerancia a caminos"
L["0 (as AzerothGPS chooses)"] = "0 (como elija AzerothGPS)"
L["Below 0, routes keep to the roads more and more; above 0, they cut straight across open ground more and more, at the top as if the roads weren't there."] = "Por debajo de 0, las rutas se ciñen cada vez más a los caminos; por encima de 0, atajan cada vez más a campo abierto, y al máximo como si no hubiera caminos."
L["Visit stops in the fastest order"] = "Visitar paradas en el orden más rápido"
L["Routes with several stops visit them in the fastest order instead of the order you placed them. (Double-click the map to place stops.)"] = "Las rutas con varias paradas las visitan en el orden más rápido en vez de en el orden en que las pusiste. (Doble clic en el mapa para poner paradas.)"
L["Except in cities"] = "Excepto en ciudades"
L["Stops down in a city (Undercity) are visited in the order you placed them among themselves: how you want to go around a city is up to you. Stops outside the city still go in the fastest order. (A quest route is always put in the fastest order.)"] = "Las paradas dentro de una ciudad (Entrañas) se visitan entre sí en el orden en que las pusiste: cómo recorrer una ciudad lo decides tú. Las paradas de fuera siguen en el orden más rápido. (Una ruta de misiones siempre va en el orden más rápido.)"
L["X on the route panel cancels the route"] = "La X del panel de ruta cancela la ruta"
L["The X at the top right of the map's route panel (the steps) cancels the whole route. Off: it only closes the panel until the route changes, and the route goes on."] = "La X de arriba a la derecha del panel de ruta del mapa (los pasos) cancela toda la ruta. Desactivado: solo cierra el panel hasta que cambie la ruta, y la ruta continúa."
L["Zeppelins, boats and the tram"] = "Zepelines, barcos y tranvía"
L["Unticked ones are never used in routes. Right-clicking a dock on the map does the same."] = "Los que no estén marcados nunca se usan en las rutas. Hacer clic derecho en un muelle del mapa hace lo mismo."
L["Zeppelins"] = "Zepelines"
L["Routes may take the zeppelin between %s and %s. Unticked: never."] = "Las rutas pueden tomar el zepelín entre %s y %s. Sin marcar: nunca."
L["Boats"] = "Barcos"
L["Routes may take the boat between %s and %s. Unticked: never."] = "Las rutas pueden tomar el barco entre %s y %s. Sin marcar: nunca."
L["The Deeprun Tram"] = "El Tranvía Subterráneo"
L["Routes may take the Deeprun Tram between %s and %s. Unticked: never."] = "Las rutas pueden tomar el Tranvía Subterráneo entre %s y %s. Sin marcar: nunca."
L["Waypoints and sharing"] = "Puntos de ruta y compartir"
L["Accept TomTom /way commands"] = "Aceptar comandos /way de TomTom"
L["/way lines typed or pasted in chat add stops to the route (several pasted lines at once become several stops). With TomTom installed, its waypoint is set too. Questie's \"Set TomTom Target\" adds a stop the same way."] = "Las líneas /way escritas o pegadas en el chat añaden paradas a la ruta (varias líneas pegadas a la vez son varias paradas). Con TomTom instalado, también se fija su punto de ruta. El \"Set TomTom Target\" de Questie añade una parada igual."
L["Questie: no map for that target"] = "Questie: no hay mapa para ese destino"
L["%s is already on your route."] = "%s ya está en tu ruta."
L["Map pin links add stops"] = "Enlaces de marcador añaden paradas"
L["Clicking a map pin someone posted in chat (\"[Map Pin Location]\") adds a stop there. To share a spot yourself, Ctrl + left-click it on the map for the map pin (a diamond, the game's own waypoint), then Shift + left-click the pin; Ctrl + left-click it again removes it."] = "Hacer clic en un marcador del mapa que alguien publicó en el chat (\"[Ubicación del marcador del mapa]\") añade una parada allí. Para compartir tú un punto, Ctrl + clic izquierdo en él en el mapa para poner el marcador (un rombo, el punto de ruta del propio juego) y luego Mayús + clic izquierdo en el marcador; otro Ctrl + clic izquierdo lo quita."
L["Accept routes shared by players"] = "Aceptar rutas compartidas por jugadores"
L["Route links other AzerothGPS users post in chat (\"[AzerothGPS Route: 3 stops]\", from the Import and Share window) can be clicked to get their route. Nothing comes in unless you click one, and you're asked before it replaces yours."] = "Puedes hacer clic en los enlaces de ruta que otros usuarios de AzerothGPS publican en el chat (\"[Ruta de AzerothGPS: 3 paradas]\", desde la ventana Importar y compartir) para recibir su ruta. No llega nada salvo que hagas clic, y se te pregunta antes de sustituir la tuya."
L["Import and Share..."] = "Importar y compartir..."
L["Directions"] = "Indicaciones"
L["Show direction arrow"] = "Mostrar flecha de dirección"
L["Two small panels (TomTom style): an arrow along the route, and beside it the directions: the next turn (\"Turn left 120 yd, toward Razor Hill\"), the stop's distance and ETA, and the stops after it when made taller."] = "Dos pequeños paneles (estilo TomTom): una flecha que sigue la ruta y, a su lado, las indicaciones: el próximo giro (\"Gira a la izquierda en 120 yd, hacia Cerrotajo\"), la distancia y hora estimada de llegada a la parada, y las paradas siguientes si lo haces más alto."
L["Lock arrow position"] = "Bloquear posición de la flecha"
L["Lock directions text position"] = "Bloquear posición del texto de las indicaciones"
L["Locks the directions text in place, apart from the arrow. Unlocked: drag it to move it and its bottom-right corner to resize it (taller lists the later stops). With no route it shows a placeholder while unlocked, so you can place it. Locked, clicks pass through it to the game world."] = "Bloquea el texto de las indicaciones en su sitio, aparte de la flecha. Desbloqueado: arrástralo para moverlo y su esquina inferior derecha para cambiar su tamaño (más alto muestra las paradas siguientes). Sin ruta muestra un marcador mientras está desbloqueado, para que puedas colocarlo. Bloqueado, los clics lo atraviesan hacia el mundo del juego."
L["Locks the arrow in place. Unlocked: drag it to move it. Snapped to the directions text, it still moves with the text while the text is unlocked. With no route it shows a placeholder while unlocked, so you can place it. Locked, clicks pass through it to the game world."] = "Bloquea la flecha en su sitio. Desbloqueada: arrástrala para moverla. Acoplada al texto de las indicaciones, se mueve con el texto mientras este esté desbloqueado. Sin ruta muestra un marcador mientras está desbloqueada, para que puedas colocarla. Bloqueada, los clics la atraviesan hacia el mundo del juego."
L["Questing objective tracker"] = "Seguimiento de objetivos de misión"
L["A stop inside a quest's area (the blue outlines, for quests in your log) is done when that quest's objectives are, not when you get there. In the area, the route waits and the arrow shows a ! and the objective counters. Leave before they're done and the route leads back; then it goes on to the next stop."] = "Una parada dentro de la zona de una misión (los contornos azules, para misiones de tu registro) se completa cuando se completan sus objetivos, no al llegar. En la zona, la ruta espera y la flecha muestra un ! y los contadores de objetivos. Si te vas antes de terminarlos, la ruta te lleva de vuelta; luego sigue a la próxima parada."
L["Arrow size"] = "Tamaño de la flecha"
L["%d px"] = "%d px"
L["Arrow background"] = "Fondo de la flecha"
L["Show the directions text"] = "Mostrar el texto de las indicaciones"
L["The panel beside the arrow with the next turn, the stop's distance and ETA and the stops after it. Off: the arrow alone, without the text."] = "El panel junto a la flecha con el próximo giro, la distancia y hora estimada de llegada a la parada y las paradas siguientes. Desactivado: solo la flecha, sin el texto."
L["List the stops only"] = "Mostrar solo las paradas"
L["The directions list the route's stops, each with its distance and ETA, without the turns (\"Continue straight, then turn left in 280 yd\")."] = "Las indicaciones muestran las paradas de la ruta, cada una con su distancia y hora estimada de llegada, sin los giros (\"Sigue recto y, en 280 yd, gira a la izquierda\")."
L["Text size"] = "Tamaño del texto"
L["Directions background"] = "Fondo de las indicaciones"
L["Snap the arrow to the directions"] = "Acoplar la flecha a las indicaciones"
L["The arrow sits against a side of the directions and the two move as one: drag the directions to move both. Unlocked, drag the arrow away to move it on its own, and drop it against a side of the directions to snap it there again."] = "La flecha se pega a un lado de las indicaciones y ambas se mueven juntas: arrastra las indicaciones para mover las dos. Desbloqueada, aparta la flecha para moverla sola, y suéltala junto a un lado de las indicaciones para volver a acoplarla."
L["Arrow side"] = "Lado de la flecha"
L["Left"] = "Izquierda"
L["Right"] = "Derecha"
L["Above"] = "Arriba"
L["Below"] = "Abajo"
L["Hide"] = "Ocultar"
L["No arrow: the directions text alone. The arrow's place shows a hearthstone or teleport to use when the route starts with one."] = "Sin flecha: solo el texto de las indicaciones. Si la ruta empieza con una piedra de hogar o un teletransporte, aparece en el lugar de la flecha para usarlo."
L["How it works"] = "Cómo funciona"
L["The arrow points along the route: |cff73ff73green|r straight ahead, |cffffffffwhite|r for a turn coming up, |cffff7359red|r when the route is behind you. On a flight it shows where you land and when."] = "La flecha señala a lo largo de la ruta: |cff73ff73verde|r recto, |cffffffffblanca|r si se acerca un giro, |cffff7359roja|r cuando la ruta queda detrás de ti. En un vuelo muestra dónde y cuándo aterrizas."
L["The directions' lines: the next turn and its distance, the road or place you're heading toward, the stop with its distance and ETA, then the turn after that. With List the stops only, just the stops."] = "Las líneas de las indicaciones: el próximo giro y su distancia, el camino o lugar hacia el que vas, la parada con su distancia y hora estimada de llegada, y el giro siguiente. Con Mostrar solo las paradas, solo las paradas."
L["Each has its own lock: untick Lock arrow position or Lock directions text position, then drag that one; drag the directions' bottom-right corner to resize them. Made taller, they list the later stops too. Unlocked with no route, they show a placeholder so you can place them."] = "Cada uno tiene su propio bloqueo: desmarca Bloquear posición de la flecha o Bloquear posición del texto de las indicaciones y arrastra ese; arrastra la esquina inferior derecha de las indicaciones para cambiar su tamaño. Más altas, muestran también las paradas siguientes. Desbloqueadas y sin ruta, muestran un marcador para que puedas colocarlas."
L["Drag the arrow off the directions to move it on its own; drop it against any side of them and it snaps there. Dragging the directions takes a snapped arrow along."] = "Aparta la flecha de las indicaciones para moverla sola; suéltala junto a cualquier lado de ellas y se acopla ahí. Al arrastrar las indicaciones, la flecha acoplada las acompaña."
L["Only the text: pick Hide under Arrow side. Only the arrow: untick Show the directions text."] = "Solo el texto: elige Ocultar en Lado de la flecha. Solo la flecha: desmarca Mostrar el texto de las indicaciones."
L["In a quest's area the arrow shows a ! and the directions the quest's objectives. A small Sprint icon pulsing in the directions' top-right corner means you picked up or finished a quest after making your quest route: click it (or the quest route button on the map) to make the route again with it or its turn-in."] = "En la zona de una misión, la flecha muestra un ! y las indicaciones los objetivos de la misión. Un pequeño icono de Sprint parpadeando en la esquina superior derecha de las indicaciones significa que aceptaste o completaste una misión después de crear tu ruta de misiones: haz clic en él (o en el botón de ruta de misiones del mapa) para volver a crear la ruta con ella o con su entrega."
L["Map style and layers: the round button at the map's bottom-left."] = "Estilo de mapa y capas: el botón redondo de abajo a la izquierda del mapa."
L["Right-click opens the world map"] = "Clic derecho abre el mapa del mundo"
L["In the OpenMap style, right-click zooms out a few steps on the same spot (each right-click a few more, up to the whole world). In the Terrain style, it shows Azeroth: click a continent, then a spot on it, to come back to the terrain view there. Right-click again goes back."] = "En el estilo OpenMap, clic derecho aleja unos pasos sobre el mismo punto (cada clic derecho, unos pocos más, hasta el mundo entero). En el estilo Terreno, muestra Azeroth: haz clic en un continente y luego en un punto de él para volver allí a la vista de terreno. Otro clic derecho vuelve atrás."
L["Building interiors"] = "Interiores de edificios"
L["Inside buildings and caves (e.g. Undercity), the terrain view shows the building's own map, like the minimap."] = "Dentro de edificios y cuevas (p. ej., Entrañas), la vista de terreno muestra el mapa propio del edificio, como el minimapa."
L["Map style"] = "Estilo de mapa"
L["OpenMap (the default): the ground seen from above, and the mouse wheel zooms on out past the land, through zones and continents to the whole world on a stitched world map, and back in to the roads. Right-click zooms out a few steps on the same spot, up to the whole world. Picked again after another style, it loads once the UI is reloaded (a prompt offers it); in the other styles nothing of it is loaded."] = "OpenMap (por defecto): el terreno visto desde arriba; la rueda del ratón aleja el zoom más allá del terreno, por zonas y continentes, hasta el mundo entero en un mapa del mundo unido, y vuelve a acercarlo hasta los caminos. Clic derecho aleja unos pasos sobre el mismo punto, hasta el mundo entero. Si se vuelve a elegir tras otro estilo, se carga al recargar la interfaz (un aviso lo ofrece); en los demás estilos no se carga nada de él."
L["Terrain: the ground alone, as far out as the land. World Map: the world map, fully explored. No Spoiler Map: the world map as your character has explored it."] = "Terreno: solo el terreno, hasta donde llega. Mapa del mundo: el mapa del mundo, totalmente explorado. Mapa sin spoilers: el mapa del mundo tal como lo ha explorado tu personaje."
L["Show only explored areas"] = "Solo zonas exploradas"
L["The OpenMap style's zone art shows only the areas this character has explored, as the game's own world map does; the rest is the zone's blank parchment. The terrain close in is never changed."] = "Las imágenes de zona del estilo OpenMap muestran solo las áreas que este personaje ha explorado, como hace el propio mapa del mundo del juego; el resto es el pergamino en blanco de la zona. El terreno de cerca nunca cambia."
L["Double-click one to add it as a stop."] = "Doble clic en uno para añadirlo como parada."
L["Flight masters"] = "Maestros de vuelo"
L["Green: known. Gray: not learned. Yellow: open a flight map once so the addon can tell."] = "Verde: conocido. Gris: no aprendido. Amarillo: abre un mapa de vuelo una vez para que el accesorio lo sepa."
L["Points of interest"] = "Puntos de interés"
L["Places marked on the world map."] = "Lugares marcados en el mapa del mundo."
L["Place names"] = "Nombres de lugares"
L["Town and area names, when zoomed in."] = "Nombres de pueblos y áreas, con el zoom acercado."
L["Your quests' objectives and turn-ins."] = "Los objetivos y entregas de tus misiones."
L["Party members"] = "Miembros del grupo"
L["Your party's or raid's members, as round icons of their class in their class's color (their name when you point at one), where the game gives their position. They don't need AzerothGPS themselves."] = "Los miembros de tu grupo o banda, como iconos redondos de su clase en el color de su clase (su nombre al apuntar a uno), donde el juego da su posición. Ellos no necesitan tener AzerothGPS."
L["Route on the minimap"] = "Ruta en el minimapa"
L["Your route on the game's minimap too, around you, and the next stop's marker (on the minimap's edge while it's further). It's drawn again only when something on it changes."] = "Tu ruta también en el minimapa del juego, a tu alrededor, y el marcador de la próxima parada (en el borde del minimapa mientras esté más lejos). Solo se redibuja cuando algo cambia en ella."
L["Icons on the minimap"] = "Iconos en el minimapa"
L["The map's icons on the game's minimap too: your pins, the herbs and ore you know, city places, party members, docks and entrances, each when it's shown on the map. Off by default."] = "Los iconos del mapa también en el minimapa del juego: tus chinchetas, las hierbas y minerales que conoces, lugares de ciudad, miembros del grupo, muelles y entradas, cada uno cuando se muestra en el mapa. Desactivado por defecto."
L["Minimap shape"] = "Forma del minimapa"
L["Automatic"] = "Automática"
L["What your minimap addon says, or the shape it gives the minimap."] = "Lo que indique tu accesorio de minimapa, o la forma que le dé al minimapa."
L["Round"] = "Redonda"
L["Square"] = "Cuadrada"
L["Quest areas on the map"] = "Zonas de misión en el mapa"
L["Quest areas on the minimap"] = "Zonas de misión en el minimapa"
L["Our outlines of your quests' objective areas on the GPS map as your minimap. Off: the game's own quest areas there instead."] = "Nuestros contornos de las zonas de objetivos de tus misiones en el mapa GPS como minimapa. Desactivado: las zonas de misión del juego en su lugar."
L["Outlines of your quests' objective areas, like on the minimap. Hover one to see the quest's objectives."] = "Contornos de las zonas de objetivos de tus misiones, como en el minimapa. Pasa el ratón por una para ver los objetivos de la misión."
L["Herbs you've gathered, hovered on the game minimap, right-clicked (without Herbalism) or imported. Saved for all your characters. A farming area (map menu) uses the kinds shown."] = "Hierbas que has recolectado, señalado con el ratón en el minimapa del juego, pulsado con clic derecho (sin Herboristería) o importado. Se guardan para todos tus personajes. Una zona de recolección (menú del mapa) usa los tipos visibles."
L["Mining nodes you've gathered, hovered on the game minimap, right-clicked (without Mining) or imported. Saved for all your characters. A farming area (map menu) uses the kinds shown."] = "Nodos de minería que has recolectado, señalado con el ratón en el minimapa del juego, pulsado con clic derecho (sin Minería) o importado. Se guardan para todos tus personajes. Una zona de recolección (menú del mapa) usa los tipos visibles."
L["Dungeons and raids"] = "Mazmorras y bandas"
L["Their entrances, on every map style. Click one for its map, with its bosses in the usual order; right-click goes back out."] = "Sus entradas, en todos los estilos de mapa. Haz clic en una para ver su mapa, con sus jefes en el orden habitual; clic derecho vuelve a salir."
L["Cave entrances"] = "Entradas de cuevas"
L["The ways into caves and mines (not on a continent's map). Double-click one for a stop there."] = "Las entradas a cuevas y minas (no en el mapa de un continente). Doble clic en una para poner una parada allí."
L["Your pins (Shift + left-click on the map: Options > Tools) and the ones shared with everyone. Double-click one for a stop there; right-click to remove it."] = "Tus chinchetas (Mayús + clic izquierdo en el mapa: Opciones > Herramientas) y las compartidas con todos. Doble clic en una para poner una parada allí; clic derecho para quitarla."
L["Frame color"] = "Color del marco"
L["AzerothGPS's own"] = "El de AzerothGPS"
L["Buttons"] = "Botones"
L["The game's own"] = "Los del juego"
L["Match the frame"] = "Igual que el marco"
L["The frame color's (above)."] = "Los del color del marco (arriba)."
L["Close button (X)"] = "Botón de cerrar (X)"
L["Same as the buttons"] = "Igual que los botones"
L["Route color"] = "Color de la ruta"
L["Rainbow"] = "Arcoíris"
L["The colors of the rainbow along the route."] = "Los colores del arcoíris a lo largo de la ruta."
L["A little celebration over the map when you reach your trip's last stop."] = "Una pequeña celebración sobre el mapa al llegar a la última parada del trayecto."
L["None"] = "Ninguno"
L["Celebration"] = "Celebración"
L["Try It"] = "Probar"
L["Charm"] = "Colgante"
L["A legendary weapon hanging on a string from the AzerothGPS logo."] = "Un arma legendaria colgada de un cordel del logotipo de AzerothGPS."
L["Swings while you move"] = "Se balancea al moverte"
L["Turning swings it out of the turn and the road jostles it; it twists on its string and settles when you stop. Off: it hangs still, facing you."] = "Al girar se balancea hacia fuera de la curva y el camino lo zarandea; se retuerce en su cordel y se calma al pararte. Desactivado: cuelga quieto, de cara a ti."
L["Keys and buttons"] = "Teclas y botones"
L["Keys"] = "Teclas"
L["Where each one goes"] = "Dónde va cada uno"
L["Always shown: next to the map button, going up or to the right. In the menu: slides out past those when you click the map button (it closes after 20 seconds untouched). Hidden: not on the map (the setting still works). A group (map style, quests, herbs and ore) is one button: click it and its buttons slide out beside it. ^ and v set the order."] = "Siempre visible: junto al botón del mapa, hacia arriba o a la derecha. En el menú: se despliega tras esos al hacer clic en el botón del mapa (se cierra tras 20 segundos sin usarlo). Oculto: no aparece en el mapa (el ajuste sigue funcionando). Un grupo (estilo de mapa, misiones, hierbas y minerales) es un solo botón: haz clic y sus botones se despliegan a su lado. ^ y v fijan el orden."
L["At the map's size: %d fit going up and %d going right (always shown and in the menu together)."] = "Con el tamaño actual del mapa caben %d hacia arriba y %d a la derecha (siempre visibles y en el menú, juntos)."
L["Always shown"] = "Siempre visible"
L["In the menu"] = "En el menú"
L["Up"] = "Arriba"
L["Hidden"] = "Oculto"
L["On"] = "Activo"
L["Earlier (nearer the map button)"] = "Antes (más cerca del botón del mapa)"
L["Later (further from the map button)"] = "Después (más lejos del botón del mapa)"
L["A group: %s."] = "Un grupo: %s."
L["No room for %s there at this map size (it would need %s). Make the map bigger (Map window: %s), or move or hide another one."] = "No hay sitio para %s ahí con este tamaño de mapa (necesitaría %s). Agranda el mapa (Ventana del mapa: %s), o mueve u oculta otro."
L["Height and Width"] = "Alto y ancho"
L["Tools"] = "Herramientas"
L["Your own marks on the map: a name and an icon."] = "Tus propias marcas en el mapa: un nombre y un icono."
L["Shift + left-click on the map, then |cffffd100Create Pin|r: name it, pick an icon (any the game has, as for a macro) and, where floors lie over each other (a dungeon, Undercity, a cave), its floor. Double-click a pin for a stop there; right-click it to remove it. Pins are shared with your map data (Copy Map Data..., Help improve)."] = "Mayús + clic izquierdo en el mapa y luego |cffffd100Crear chincheta|r: ponle nombre, elige un icono (cualquiera del juego, como para una macro) y, donde hay plantas superpuestas (una mazmorra, Entrañas, una cueva), su planta. Doble clic en una chincheta para poner una parada allí; clic derecho para quitarla. Las chinchetas se comparten con tus datos del mapa (Copiar datos del mapa..., Ayuda a mejorar)."
L["Pinning"] = "Chinchetas"
L["Shift + left-click on the map asks to create a pin there. Off: Shift + left-drag only moves the map's window."] = "Mayús + clic izquierdo en el mapa pregunta si crear una chincheta allí. Desactivado: Mayús + arrastrar con clic izquierdo solo mueve la ventana del mapa."
L["Help improve AzerothGPS"] = "Ayuda a mejorar AzerothGPS"
L["Kept on your PC only; sharing it is a separate step."] = "Se guarda solo en tu PC; compartirlo es un paso aparte."
L["How to share..."] = "Cómo compartir..."
L["Type |cffffd100/reload|r before |cffffd100Copy Map Data...|r: it saves all your road and wall edits and pins, so every one of them is in the copy."] = "Escribe |cffffd100/reload|r antes de |cffffd100Copiar datos del mapa...|r: guarda todos tus cambios de caminos y muros y tus chinchetas, para que todos estén en la copia."
L["What Copy Map Data... includes"] = "Qué incluye Copiar datos del mapa..."
L["Untick what you'd rather keep to yourself: it's left out of the copy."] = "Desmarca lo que prefieras guardarte: se excluye de la copia."
L["%s Unticked: left out of the copy."] = "%s Sin marcar: se excluye de la copia."
L["Waiting to be shared: %s, %s, %s, %s"] = "Pendiente de compartir: %s, %s, %s, %s"
L["%d road"] = "%d camino"
L["%d wall"] = "%d muro"
L["%d pin"] = "%d chincheta"
L["%d trip"] = "%d trayecto"
L["%d trips"] = "%d trayectos"
L["Thanks"] = "Agradecimientos"
L["%s options failed:"] = "Fallaron las opciones de %s:"
L["Reset to defaults"] = "Restablecer valores por defecto"
L["Left-click: show/hide the GPS"] = "Clic izquierdo: mostrar/ocultar el GPS"
L["Right-click: options"] = "Clic derecho: opciones"
L["Drag: move this button"] = "Arrastrar: mover este botón"
L["Car-GPS style map and navigation. Settings are in the AzerothGPS window."] = "Mapa y navegación al estilo de un GPS de coche. Los ajustes están en la ventana de AzerothGPS."
L["Open AzerothGPS options"] = "Abrir opciones de AzerothGPS"
L["Name"] = "Nombre"
L["Choose an icon:"] = "Elige un icono:"
L["Saved at logout or /reload"] = "Se guarda al desconectarte o con /reload"
L["Floor: %s"] = "Planta: %s"
L["Floor: every floor here"] = "Planta: todas las de aquí"
L["Icons %d-%d of %d (mouse wheel scrolls)"] = "Iconos %d-%d de %d (la rueda del ratón desplaza)"
