L["For a pair, hold %s, then press the other button."] = "Para una pareja, mantén %s y pulsa el otro botón."
L["%s is %s: use it for Show/Hide GPS instead?"] = "%s es %s: ¿usarlo para Mostrar/Ocultar GPS en su lugar?"
L["Press the controller button for Show/Hide GPS. Hold B or press Escape to cancel."] = "Pulsa el botón del mando para Mostrar/Ocultar GPS. Mantén B o pulsa Escape para cancelar."
L["Text box"] = "Cuadro de texto"
